(* [comment removed for export] *)
Lemma cstr_pack : forall Σ m p bs n, ART RT Σ m -> cstr (rt_live RT Σ) m p bs -> In (p, n) (rt_live RT Σ) ->
  Z.of_nat (length bs) + 1 <= n ->
  exists slack, bytes_at asegs m p (map (Z_to_bv 8) bs ++ Z_to_bv 8 0 :: slack)
    /\ (- (p + Z.of_nat (length bs) + 1)) mod 8 <= Z.of_nat (length slack)
    /\ p + Z.of_nat (length bs) + 1 + Z.of_nat (length slack) <= rt_sp0 RT Σ - STACK_WIN.
